import random

# List of joke categories and corresponding jokes
joke_categories = [
    ("Puns", [
        "Why did the scarecrow win an award? Because he was outstanding in his field.",
        "Why did the scarecrow win an election? Because he was the head of the corn!",
    ]),
    ("One-Liners", [
        "Why don't scientists trust atoms? Because they make up everything.",
        "Why did the scarecrow win an election? Because he was the head of the corn!",
    ]),
    ("Dad Jokes", [
        "Why did the scarecrow win an award? Because he was outstanding in his field.",
        "Why did the scarecrow win an election? Because he was the head of the corn!",
    ]),
]

def get_random_joke(category):
    """Get a random joke from the given category."""
    for joke_category in joke_categories:
        if joke_category[0] == category:
            return random.choice(joke_category[1])
    return "Sorry, I couldn't find a joke in the specified category."

if __name__ == "__main__":
    user_input = input("Enter a joke category (or 'quit' to exit): ").lower()

    while user_input != "quit":
        joke = get_random_joke(user_input)
        print(f"Random joke: {joke}")
        user_input = input("Enter a joke category (or 'quit' to exit): ").lower()
```

This program defines a function `get_random_joke` that takes a category as input and returns a random joke from the corresponding list. The main part of the program prompts the user to enter a joke category and prints the random joke until the user enters 'quit'.
